using (SqlConnection connection = new SqlConnection(connectionString))
{
    connection.Open();
    SqlTransaction transaction = connection.BeginTransaction();

    try
    {
        // Decrease quantity of item #1
        using (SqlCommand command1 = new SqlCommand(
            "UPDATE Inventory SET Quantity = Quantity - 1 WHERE Id = @Id1", connection, transaction))
        {
            command1.Parameters.AddWithValue("@Id1", 1);
            command1.ExecuteNonQuery();
        }

        // Increase quantity of item #2
        using (SqlCommand command2 = new SqlCommand(
            "UPDATE Inventory SET Quantity = Quantity + 1 WHERE Id = @Id2", connection, transaction))
        {
            command2.Parameters.AddWithValue("@Id2", 2);
            command2.ExecuteNonQuery();
        }

        transaction.Commit();
    }
    catch (Exception ex)
    {
        transaction.Rollback();
        // Log the error
        Console.WriteLine($"Transaction failed: {ex.Message}");
    }
}

public bool TryUpdateInventory(Inventory model)
{
    try
    {
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            connection.Open();
            using (SqlTransaction transaction = connection.BeginTransaction())
            using (SqlCommand command = new SqlCommand(
                "UPDATE Inventory SET Price = @Price, Quantity = @Quantity WHERE Id = @Id",
                connection, transaction))
            {
                command.Parameters.AddWithValue("@Id", model.Id);
                command.Parameters.AddWithValue("@Price", model.Price);
                command.Parameters.AddWithValue("@Quantity", model.Quantity);

                int rows = command.ExecuteNonQuery();
                transaction.Commit();
                return rows > 0;
            }
        }
    }
    catch (SqlException ex)
    {
        // Handle SQL-specific errors (deadlocks, timeouts, constraint violations)
        Console.WriteLine($"SQL Error {ex.Number}: {ex.Message}");
        return false;
    }
    catch (Exception ex)
    {
        // Handle general errors
        Console.WriteLine($"Error: {ex.Message}");
        return false;
    }
}
